ic-bezier(0.34, 1.56, 0.64, 1); }.ncta span svg { width: 13px; }.ncta:hover { background: linear-gradient(120deg, rgb(58, 15, 153), rgb(192, 74, 39)); }.ncta:hover span { transform: rotate(-45deg); }.hero2:not(.blk) { padding-top: 92px; }@media (max-width: 640px) {
